#include <aether/aether.h>
#include "native/src/dom/dom_types.h"
#include "native/src/style_runtime/style_runtime_types.h"
#include "native/src/style_runtime/ua_stylesheet.h"
#include <fstream>
#include <iterator>
#include <iostream>
#include <functional>
#include "native/src/style_runtime/css_scope_proof.h"
int main(int argc,char**argv){std::ifstream f(argv[1]);std::string s((std::istreambuf_iterator<char>(f)),{});aether_doc_t d{};aether_doc_create(&d);aether_doc_parse_html(d,s.c_str());size_t nodes=0,elem=0,depth=0,siblings=0,bytes=0;std::vector<std::string>sheets;std::function<void(aether_node_t,size_t)> walk=[&](auto n,size_t dep){++nodes;elem+=n->type==AETHER_NODE_ELEMENT;depth=std::max(dep,depth);siblings=std::max(siblings,n->children.size());if(n->tag_name=="style"){std::string css;for(auto c:n->children)css+=c->text;bytes+=css.size();sheets.push_back(css);}for(auto c:n->children)walk(c,dep+1);};walk(d,1);std::cout<<"nodes="<<nodes<<" elements="<<elem<<" depth="<<depth<<" maxsiblings="<<siblings<<" CSSbytes="<<bytes<<" sheets="<<sheets.size()<<"\n";aether_style_runtime_t rt{};aether_style_environment_t env{1280,720,1,16,0,0,0};aether_style_runtime_create(nullptr,&env,nullptr,nullptr,&rt);int64_t h{};int32_t nr{};for(auto&css:sheets){auto* article=aether_doc_get_element_by_id(d,"FLEX-001");aether_node_t target{};std::function<void(aether_node_t)> find=[&](auto n){if(n->attributes.count("class")&&n->attributes.at("class")=="flex-target demo-box")target=n;for(auto c:n->children)find(c);};find(article);aether::style::css_scope::Proof proof(d,target);auto e=proof.inspect(css);size_t absent=0,maybe=0,unknown=0;size_t reasons[7]{};for(auto x:e.rules){++reasons[(int)x.reason];absent+=x.scope==aether::style::css_scope::Scope::proven_disjoint;maybe+=x.scope==aether::style::css_scope::Scope::may_affect_scope;unknown+=x.scope==aether::style::css_scope::Scope::unknown;}std::cout<<"boundary_complete="<<e.boundary_complete<<" source_rules="<<e.rules.size()<<" disjoint="<<absent<<" may_affect="<<maybe<<" UNKNOWN="<<unknown<<" queries="<<proof.queries<<" remaining="<<proof.remaining<<"\n";for(int j=0;j<7;++j)std::cout<<"reason"<<j<<"="<<reasons[j]<<" ";std::cout<<"\n";std::vector<compiled_rule_s> compiled;int32_t rid=0;style_source_accounting_s accounting;auto rc=style_source_compile(css.c_str(),1,1,compiled,rid,nullptr,nullptr,&accounting);std::cout<<"compile_status="<<rc<<" losses="<<accounting.losses<<" inputs_accounted="<<accounting.inputs_accounted<<" declarations="<<accounting.declarations<<" source_rules_accounted="<<accounting.rules<<"\n";aether_style_runtime_add_stylesheet(rt,css.c_str(),1,"original",&h,&nr);std::cout<<"compiledrules="<<nr<<"\n";}aether_style_runtime_destroy(rt);aether_doc_destroy(d);}
